"""system_report.py : writes docs/system_observations.md from work/system_corpus.pkl (anonymous labels only)."""
import sys, os, pickle, collections, json
ROOT = os.path.join(os.path.dirname(__file__), "..")
recs = pickle.load(open(os.path.join(ROOT, "work", "system_corpus.pkl"), "rb")); names = [r["name"] for r in recs]; N = len(recs)
col = lambda f: " | ".join(f(r) for r in recs)
def entries(r, prefix):
    d = collections.OrderedDict()
    for p, v in r["leaves"].items():
        if p.startswith(prefix + "/"): d.setdefault(p[len(prefix) + 1:].split("/")[0], []).append(v)
    return [tuple(v) for v in d.values()]
empty = lambda t: all(x in (0, False, None, 4294967295) for x in t)
LISTS = [("tutorial_unlock_data_", "SystemPlayerRecordData"), ("futago_doll_unlock_data_", "SystemPlayerRecordData"), ("document_unlock_data_", "SystemPlayerRecordData"), ("omamori_unlock_data_", "SystemPlayerRecordData"), ("reiseki_unlock_data_", "SystemPlayerRecordData"),
         ("ghost_list_unlock_data_", "SystemPlayerRecordData"), ("side_story_unlock_data_", "SystemPlayerRecordData"), ("yobimodoshi_unlock_data_", "SystemPlayerRecordData"), ("chibarai_unlock_data_", "SystemPlayerRecordData"),
         ("played_rtm_data_", "SystemPlayerRecordData"), ("played_prm_data_", "SystemPlayerRecordData"), ("is_played_rtm_", "SystemData")]
S = {k: [{t for t in entries(r, f"/{sec}/{k}") if not empty(t)} for r in recs] for k, sec in LISTS}
tot = [sum(len(S[k][i]) for k in S) for i in range(N)]; order = sorted(range(N), key=lambda i: tot[i])
leaf = lambda r, p: r["leaves"][p]
T = ["# System save (SYSTEMSAVEDATA00): what the samples show", "",
 "**Observed in 6 unique system saves of other players (7 files on disk, one duplicate), uncontrolled.** Nothing here was tested in the game; every system field in `docs/system_fields.json` is `guessed` and **read-only**, and the tools refuse to edit or write system saves. Labels: letters = anonymous sources; the part after `/` is the uploader's own tag for that file (a hint, not proof). Generated by `tools/system_report.py` from `tools/system_analysis.py`.", "",
 "## 1. Container and structure", "",
 f"- Magic `WLNSYS`, size 61,851,984 bytes (payload 61,851,728). It decrypts with the **same AES-128-CBC key and IV** as user saves, and both checksums (0x50, 0x70) verify: **{sum(1 for r in recs if not r['problems'])}/{N} unique files, 7/7 files on disk, byte-exact round trip.**",
 "- Header: 0x1C and every game-state field (0x20..0x48) are 0; only the magic, version, length, user-ID field, timestamp (0x30), the two checksums and the non-zero encrypted flag (0x4C) are filled. The plaintext starts with the same 16-byte prefix as user saves.",
 f"- JSON starts at plaintext offset 16 and is {min(r['end'] for r in recs)-16:,}..{max(r['end'] for r in recs)-16:,} bytes; the same 5 top-level sections and the same 21,853 leaf paths (all ints and bools) in all six saves.", "",
 "| section | bytes (first save) | keys | leaf values |", "|---|---|---|---|"]
r0 = recs[0]
for k, v in r0["obj"].items(): T.append(f"| `{k}` | {len(json.dumps(v, separators=(',', ':'))):,} | {len(v)} | {sum(1 for p in r0['leaves'] if p.startswith('/' + k + '/')):,} |")
T += ["", "- **After the JSON** the payload is zero padding and binary data whose amount differs a lot between saves; it is not decoded here:", "", "| save | JSON bytes | non-zero bytes after JSON | first non-zero byte (plaintext offset) |", "|---|---|---|---|"]
for r in recs: T.append(f"| {r['name']} | {r['end']-16:,} | {r['nz_after']:,} | {r['first_nz'] if r['first_nz'] is not None else 'none'} |")
T += ["", "The first non-zero offset is 1,024,016 in one save (the same place user saves keep their binary tail), 17,613,392 in four, and none in one save that has no binary data at all. The meaning of these regions (photos?) is **unknown**.", "",
 "## 2. What varies between the six saves", "",
 "7,377 of the 21,853 leaf values differ in at least one save, almost all in photo / ghost-list data and in the unlock lists. Areas with the most differing values: ghost-list photos (4,891), per-ghost UI data (1,323), `ghost_list_unlock_data_` (375), `omamori_unlock_data_` (210), `document_unlock_data_` (121); then key bindings, `record_save_data` (49), futago/reiseki/chibarai/yobimodoshi lists, played-scene lists and settings.", "",
 "### Small fields, per save", "", "| field | " + " | ".join(names) + " |", "|---|" + "---|" * N]
def row(label, f): T.append(f"| {label} | " + col(f) + " |")
row("`shop_point_`", lambda r: f"{leaf(r, '/SystemPlayerRecordData/shop_point_'):,}")
for i in range(5): row(f"`ending_cleared_flag_[{i}]`", lambda r, i=i: str(leaf(r, f"/SystemPlayerRecordData/ending_cleared_flag_/{i}")))
row("`costume_bit_flag_`", lambda r: str(leaf(r, "/SystemData/costume_bit_flag_"))); row("`photo_sticker_bit_flag_`", lambda r: str(leaf(r, "/SystemData/photo_sticker_bit_flag_"))); row("`photo_frame_bit_flag_`", lambda r: str(leaf(r, "/SystemData/photo_frame_bit_flag_")))
row("`setting_language_[0]`", lambda r: str(leaf(r, "/SystemData/setting_language_/0"))); row("`setting_controller_base_operate`", lambda r: str(leaf(r, "/SystemData/setting_controller_base_operate")))
row("`setting_audio_[0]`", lambda r: str(leaf(r, "/SystemData/setting_audio_/0")))
T += ["", "- `shop_point_` is huge in the four advanced saves (up to 180 million) and 0 in the two freshest; whether it is a balance or a lifetime total is unknown. It is not the per-playthrough points of a user save.",
 "- `ending_cleared_flag_`: five booleans (probably one per ending). [0] is True in 5 of 6 saves, [1]..[4] only in the two fully unlocked saves. Source A's 100% user save has `current_end_` = 5, and so do 2 of source B's 12 NG+ practice user saves (see `docs/field_proposals.md`); a link between the two is only a guess.",
 "- `costume_bit_flag_`, `photo_sticker_bit_flag_` and `photo_frame_bit_flag_` look like bit masks that are non-zero/full only in the fully unlocked saves (0x7FFFFFFF for stickers).",
 "- The `setting_*` arrays are player options (language, audio volumes, graphics, key bindings, controller): they differ per player, not with progress.", "",
 "### Unlock lists", "",
 "The `*_unlock_data_` lists, `played_*` lists and `is_played_*` lists are **zero-padded lists of hashed ids stored in unlock order**: the same ids appear at different positions in different saves, so they must be compared as sets. Non-empty entries per save:", "",
 "| list | size | " + " | ".join(names) + " |", "|---|---|" + "---|" * N]
for k, sec in LISTS: T.append(f"| `{k}` | {len(entries(recs[0], f'/{sec}/{k}'))} | " + " | ".join(str(len(S[k][i])) for i in range(N)) + " |")
T += ["| **total** | | " + " | ".join(str(t) for t in tot) + " |", "", "Is each save's set of unlocked entries contained in another save's set? Number of lists (of 12) in which the row's set is a subset of the column's set:", "",
      "| row \\ column | " + " | ".join(names[j] for j in order) + " |", "|---|" + "---|" * N]
for i in order: T.append(f"| {names[i]} | " + " | ".join(str(sum(1 for k in S if S[k][i] <= S[k][j])) for j in order) + " |")
a, g = names.index("A/-"), names.index("B/NG+"); same = sum(1 for k in S if S[k][a] == S[k][g]); dpaths = sum(1 for p in recs[a]["leaves"] if recs[a]["leaves"][p] != recs[g]["leaves"][p])
T += ["", f"- Every save's unlocks are a subset of the two fully unlocked saves' in 12 of 12 lists. The two fully unlocked saves (A and B/NG+) have **identical unlock sets in {same} of 12 lists**; they differ in only {dpaths} of 21,853 values (mostly ghost-photo data, key bindings, graphics options and a few records). That is consistent with B's NG+ file having been built from the same fully unlocked save; it is not proof.",
 "- Source B's saves nest into each other (freshest <= nightmare <= nm-practice <= NG+). Source C is a different player and does not nest inside B's nm-practice save (7 of 12 lists).", "",
 "## 3. What is known and unknown", "",
 "**Known (reproduced on all 6 unique files):** codec, both checksums, JSON structure, 108 leaf-path patterns, that the header holds no game state, that nothing in the JSON refers to the user ID.", "",
 "**Guessed (all of `docs/system_fields.json`):** which list is which (names only), that the lists are sets of hashed ids in unlock order, that the bit flags are unlock masks, that the ending flags are per ending.", "",
 "**Unknown:** what the hashed ids are (no name table), what the binary data after the JSON is, whether the game accepts an edited system save (never tested; editing is not supported), what `shop_point_` counts, how `record_save_data` (500 records, 62 filled in every save) is used, the meaning of 0x4C and the user-ID field in a system save (same rules as user saves are assumed).", "",
 "## 4. Loading a 61 MB file (measured on macOS, CLI `info`, three runs each)", "", "| file | wall time | peak memory |", "|---|---|---|", "| user save (9.3 MB) | 0.08 s | 97 MB |", "| system save (61.9 MB) before trimming | 0.11 s | 304 MB |", "| system save after sharing the read-only buffer | 0.12 s | 256 MB |", "",
 "The system save is decrypted in about 0.1 s. The app does not decrypt it just to draw the slot list (only the 256-byte header is read), shows one summary row per list instead of thousands of rows, and the hex view is virtualized, so **no different loading approach is needed.** A byte-exact re-encryption (`verify --roundtrip`) needs about 490 MB because it holds a second copy.", ""]
open(os.path.join(ROOT, "docs", "system_observations.md"), "w").write("\n".join(T) + "\n"); print(len(T), "lines")
